@dataclass(slots=True)
class FirstOrderPass:
    """Own one forward/reverse evaluation and its explicit diagnostic checkpoint.

    Use as a context manager; pass .tape into canonical forward operators.
    Call backward after exiting the context. Keep original inputs immutable
    until close(). A new iteration requires a fresh context entry after close.
    """

    workspaces: Sequence[CheckedWorkspace]
    tape: Any = field(default=None, init=False, repr=False)
    _state: str = field(default="new", init=False)

    def __enter__(self) -> FirstOrderPass:
        if self._state != "new":
            raise ContractError("a FirstOrderPass owns exactly one evaluation")
        require_no_tape()
        for workspace in self.workspaces:
            workspace.clear_status()
        self.tape = load_warp().Tape()
        self.tape.__enter__()
        self._state = "recording"
        return self

    def __exit__(self, exc_type: Any, exc_value: Any, traceback: Any) -> None:
        self.tape.__exit__(exc_type, exc_value, traceback)
        self._state = "recorded"
        if exc_type is not None:
            self.close()

    def backward(self, output: Any, seed: Any) -> None:
        """Seed a caller-owned output cotangent and complete numerical checks."""
        if self._state != "recorded":
            raise ContractError("backward requires one completed, unconsumed forward pass")
        try:
            wp = load_warp()
            if not isinstance(output, wp.array) or output.grad is None:
                raise ContractError("output must be a Warp CUDA array with a preallocated gradient")
            ctx = prepare_context(device=output.device)
            ctx.array(output, "output", dtype=output.dtype, ndim=output.ndim)
            ctx.array(seed, "seed", dtype=output.dtype, shape=tuple(output.shape), ndim=output.ndim)
            self.tape.backward(grads={output: seed})
            for workspace in self.workspaces:
                workspace.check_status()
            self._state = "complete"
        except BaseException:
            self.close()
            raise

    def close(self) -> None:
        """Clear accumulated cotangents and release every abandoned recording."""
        if self._state == "recording":
            raise ContractError("exit the recording context before closing it")
        if self.tape is not None and self._state != "closed":
            self.tape.zero()
            self.tape.reset()
            for workspace in self.workspaces:
                discard = getattr(workspace, "discard_recording", None)
                if discard is not None:
                    discard(self.tape)
        self._state = "closed"

def package_identity() -> str:
    """Return the stable package name used by bootstrap wiring checks."""
    return "differentiable-photon-transport"

def target_jacobians(np: Any, pose: RigidTransform, targets: Any, scales: Any) -> Any:
    """Return d(world target)/dz in mm for T_WO exp((S z)^) at z=0."""
    rotation = np.asarray(pose.rotation, dtype=np.float64).reshape(3, 3)
    result = np.empty((len(targets), 3, 6), dtype=np.float64)
    for index, (x, y, z) in enumerate(targets):
        skew = np.asarray([[0.0, -z, y], [z, 0.0, -x], [-y, x, 0.0]])
        result[index, :, :3] = rotation
        result[index, :, 3:] = -rotation @ skew
    result *= scales[None, None, :]
    if not np.isfinite(result).all():
        raise NumericalError("target derivatives exceed FP64; check target coordinates and scales")
    return result


def target_variance(
    np: Any, precision: Any, target_jacobian: Any, maximum_condition: float
) -> tuple[float, Any, float]:
    """Mean target-position variance in mm², without forming an inverse to score."""
    if not np.isfinite(precision).all():
        raise NumericalError("pose precision is non-finite; discard this candidate score")
    values = np.linalg.eigvalsh(precision)
    if values[0] <= 0 or values[-1] / values[0] > maximum_condition:
        raise NumericalError(
            "pose precision must be positive definite and within maximum_precision_condition; "
            "check the stated uncertainty and parameter scales, without adding numerical jitter"
        )
    factor = np.linalg.cholesky(precision)
    right = target_jacobian.reshape(-1, 6).T
    whitened = np.linalg.solve(factor, right)
    if not np.isfinite(whitened).all():
        raise NumericalError(
            "target covariance solve exceeds FP64; check the precision and chart scales"
        )
    # hypot scales its sum of squares; individual products must not underflow
    # before they contribute to an otherwise representable total variance.
    normalisation = math.sqrt(len(target_jacobian))
    root_variance = math.hypot(*(float(value) / normalisation for value in whitened.flat))
    variance = root_variance * root_variance
    if not math.isfinite(variance) or variance <= 0:
        raise NumericalError(
            "positive target-position variance is outside FP64 range; check the stated "
            "uncertainty and physical units, or use a range-preserving score representation"
        )
    inverse_factor = np.linalg.solve(factor, np.eye(6))
    covariance = inverse_factor.T @ inverse_factor
    if not np.isfinite(covariance).all() or bool((np.diag(covariance) <= 0).any()):
        raise NumericalError(
            "local covariance is outside FP64 range; check the precision and chart scales "
            "before exporting this candidate"
        )
    return variance, covariance, float(values[-1] / values[0])

class SharedPoseObjective:
    """Sum views in one immutable chart; each evaluator owns its image scratch."""

    def __init__(self, views: tuple[PreparedView, ...], chart: PoseChart) -> None:
        if not views or any(view.evaluator.chart is not chart for view in views):
            raise ContractError("all views must share the same PoseChart object")
        self.views, self.chart = views, chart

    def __call__(self, parameters: Vector) -> Evaluation:
        values = tuple(view.evaluator(parameters) for view in self.views)
        return Evaluation(
            math.fsum(value.loss for value in values),
            tuple(math.fsum(value.gradient[k] for value in values) for k in range(6)),
        )

@dataclass(frozen=True, slots=True)
class RigidTransform:
    """T_WO maps object points into world coordinates; translation is in mm."""

    rotation: Matrix3 = IDENTITY
    translation_mm: Vector3 = (0.0, 0.0, 0.0)

    def __post_init__(self) -> None:
        object.__setattr__(self, "rotation", rotation_matrix(self.rotation))
        object.__setattr__(self, "translation_mm", vector3(self.translation_mm, "translation"))

    def point(self, point_mm: Vector3) -> Vector3:
        rotated = matvec(self.rotation, point_mm)
        return cast(Vector3, tuple(rotated[i] + self.translation_mm[i] for i in range(3)))

    def direction(self, direction: Vector3) -> Vector3:
        return matvec(self.rotation, direction)

    def inverse(self) -> RigidTransform:
        inverse_rotation = transpose(self.rotation)
        translation = matvec(inverse_rotation, self.translation_mm)
        return RigidTransform(inverse_rotation, cast(Vector3, tuple(-x for x in translation)))

    def compose(self, right: RigidTransform) -> RigidTransform:
        """Return self @ right; the right-hand map is applied first."""
        return RigidTransform(
            matmul(self.rotation, right.rotation), self.point(right.translation_mm)
        )

    def packed(self) -> tuple[float, ...]:
        """Twelve float64 device values: row-major rotation, then translation."""
        return (*self.rotation, *self.translation_mm)

@cache
def evaluation_kernel(
    poisson: bool,
    weighted: bool,
    gradient: bool,
    masked: bool = False,
    precision: str = "float32",
):
    value_dtype = wp.float64 if precision == "float64" else wp.float32

    @wp.kernel(module="unique", module_options=OPTIONS)
    def evaluate(
        prediction: wp.array(dtype=value_dtype),
        observation: wp.array(dtype=wp.float32),
        weights: wp.array(dtype=wp.float32),
        valid: wp.array(dtype=wp.uint8),
        size: int,
        normalisation: wp.float64,
        seed: wp.array(dtype=value_dtype),
        partials: wp.array(dtype=wp.float64),
        status: wp.array(dtype=wp.int32),
    ):
        block, lane = wp.tid()
        p = block * TILE + lane
        loss = wp.float64(0.0)
        if p < size:
            active = bool(True)  # noqa: UP018 - Warp runtime Boolean.
            if wp.static(masked):
                if valid[p] > wp.uint8(1):
                    wp.atomic_or(status, 0, 1)
                active = valid[p] == wp.uint8(1)
            if active:
                predicted = wp.float64(prediction[p])
                observed = wp.float64(observation[p])
                weight = normalisation
                if wp.static(weighted):
                    weight *= wp.float64(weights[p])
                difference = predicted - observed
                derivative = difference
                loss = wp.float64(0.5) * difference * difference
                if wp.static(poisson):
                    if observed == wp.float64(0.0):
                        loss = predicted
                        derivative = wp.float64(1.0)
                    else:
                        derivative = difference / predicted
                        loss = poisson_half_deviance(predicted, observed)
                if wp.static(precision == "float64" and not poisson):
                    # A small fixed weight can keep the final squared loss
                    # representable even when the unweighted square overflows.
                    loss = (wp.float64(0.5) * weight * difference) * difference
                else:
                    loss *= weight
                if not wp.isfinite(loss):
                    wp.atomic_or(status, 0, 2)
                if wp.static(gradient):
                    weighted_derivative = weight * derivative
                    if wp.static(precision == "float64" and poisson):
                        if not wp.isfinite(derivative):
                            # FP32 observations/weights bound this numerator;
                            # do not overflow a removable unweighted quotient.
                            weighted_derivative = (weight * difference) / predicted
                    result = value_dtype(weighted_derivative)
                    seed[p] = result
                    if not wp.isfinite(result):
                        wp.atomic_or(status, 0, 2)
            elif wp.static(gradient):
                seed[p] = value_dtype(0.0)
        total = wp.tile_sum(wp.tile(loss))
        wp.tile_store(partials, total, offset=block)

    return evaluate

@cache
def get_forward(double_output: bool = False, cell_gauss: bool = False):
    dtype = wp.float64 if double_output else wp.float32

    @wp.kernel(module="unique", module_options=OPTIONS)
    def forward(
        field: wp.array(dtype=wp.float32),
        pose: wp.array(dtype=wp.float64),
        config: Configuration,
        output: wp.array(dtype=dtype),
        status: wp.array(dtype=wp.int32),
    ):
        pixel = wp.tid()
        ray = ray_for_pixel(config, pose, pixel)
        if not valid_ray(ray):
            wp.atomic_or(status, 0, 2)
            output[pixel] = dtype(0.0)
            return
        interval = finite_interval(ray.origin, ray.direction, config.shape)
        integral = wp.float64(0.0)
        if interval.upper > interval.lower:
            if wp.static(cell_gauss):
                traversal = begin_cells(ray, interval, config.shape)
                start = interval.lower
                segments = wp.int64(0)
                limit = (
                    wp.int64(config.shape[0])
                    + wp.int64(config.shape[1])
                    + wp.int64(config.shape[2])
                    + wp.int64(1)
                )
                while start < interval.upper and segments < limit:
                    end = wp.min(traversal.next[0], wp.min(traversal.next[1], traversal.next[2]))
                    if end <= start:
                        wp.atomic_or(status, 0, 2)
                        break
                    radius = (end - start) * wp.float64(0.5)
                    centre = start + radius
                    offset = radius / wp.sqrt(wp.float64(3.0))
                    for node in range(2):
                        position = centre + wp.float64(2 * node - 1) * offset
                        integral += (
                            radius
                            * sample_field(
                                field, ray.origin + position * ray.direction, config.shape
                            ).value
                        )
                    start = end
                    traversal = advance_cells(traversal, ray, config.shape, end, interval.upper)
                    segments += wp.int64(1)
                if start < interval.upper:
                    wp.atomic_or(status, 0, 2)
                integral *= ray.length
            else:
                step = (interval.upper - interval.lower) / wp.float64(config.samples)
                for sample in range(config.samples):
                    position = interval.lower + (wp.float64(sample) + wp.float64(0.5)) * step
                    point = ray.origin + position * ray.direction
                    if not finite_point(point):
                        wp.atomic_or(status, 0, 2)
                    integral += sample_field(field, point, config.shape).value
                integral *= ray.length * step
        output[pixel] = dtype(integral)
        if not wp.isfinite(output[pixel]):
            wp.atomic_or(status, 0, 2)

    return forward

